# Analyze pattern by looking at blocks for specific input cells
def get_block(r, c, output_grid):
    rows = output_grid[r*3:(r+1)*3]
    cols_start = c*3
    return [rows[i][cols_start:cols_start+3] for i in range(3)]

# Check blocks for different input cell values
# Find all cells with value 1 in input
print("Input cells with value 1:")
for i in range(8):
    for j in range(6):
        if input_grid[i][j] == 1:
            block = get_block(i, j, output_grid)
            print(f"input[{i},{j}]=1, block:")
            for row in block:
                print("  " + " ".join(map(str, row)))
            print()

# Look at specific rows to understand pattern better
# Output row 5 has 7 7 in the middle
print("Row 5:", output_grid[5])
print("Row 10:", output_grid[10])
print()

# Let's find where 7 appears in output
for r in range(24):
    for c in range(12):
        if output_grid[r][c] == 7:
            print(f"7 at output[{r},{c}]")

# Search for input pattern in the output
# Let's check if input appears as a subgrid somewhere in output

# Try searching at position (0,0) in output (checking 8x6 window)
found = False
for r in range(24-8+1):
    for c in range(12-6+1):
        match = True
        for i in range(8):
            for j in range(6):
                if output_grid[r+i][c+j] != input_grid[i][j]:
                    match = False
                    break
            if not match:
                break
        if match:
            found = True
            print(f"Found input pattern at output[{r},{c}]")
            break
    if found:
        break

if not found:
    print("Input pattern NOT found as exact subgrid")

# Let's print some middle sections of output to see if there's a pattern
print("\nOutput rows 8-16:")
for r in range(8, 16):
    print(f"Row {r}: {output_grid[r]}")

# Check for multiple copies of input pattern
positions = []
for r in range(24-8+1):
    for c in range(12-6+1):
        match = True
        for i in range(8):
            for j in range(6):
                if output_grid[r+i][c+j] != input_grid[i][j]:
                    match = False
                    break
            if not match:
                break
        if match:
            positions.append((r, c))

print("Input pattern found at positions:", positions)

# Also let's check if the output has a different fundamental structure
# Maybe it's not about copying the input but about something else
print("\nLet's examine corners of output:")
print("Top-left 8x6 block (output[0:8, 0:6]):")
for r in range(8):
    print("  " + " ".join(map(str, output_grid[r][0:6])))

# Let me check what the 7 values in input correspond to in output
# Input has 7 only at [2,0]

# Check all output positions that map to input[2,0] range (rows 6-8, cols 0-2)
print("Input[2,0] = 7, corresponding output[6:9, 0:3]:")
for r in range(6, 9):
    for c in range(0, 3):
        print(f"  output[{r},{c}] = {output_grid[r][c]}")

# Also check where 7s appear in output that DON'T map to input[2,0]
# output[5,5], output[5,6], output[10,5], output[10,6], output[21,5], output[21,6]
for r, c in [(5,5), (5,6), (10,5), (10,6), (21,5), (21,6)]:
    source = (r//3, c//3)
    print(f"output[{r},{c}]=7 maps to input{source}={input_grid[source[0]][source[1]]}")

# This 7 pattern doesn't seem to directly relate to input[2,0]
# Let me check if there's a different pattern
print("\nLet me check the full output for the value 7 distribution")
for r in range(24):
    for c in range(12):
        if output_grid[r][c] == 7:
            print(f"7 at output[{r},{c}]")

# Find all positions of each value in the input demo
from collections import defaultdict
value_positions = defaultdict(list)
for r in range(8):
    for c in range(6):
        value = input_grid[r][c]
        value_positions[value].append((r, c))

for val in sorted(value_positions.keys()):
    print(f"Value {val} at positions: {value_positions[val]}")
